-- AI LAB HUB — партія 2026-10-01: «Розробка та IT» → нова підкатегорія «No-code / Low-code» — 7 нових продуктів, 2 прив'язок наявних
--   Lovable — No-code / Low-code
--   Bolt.new — No-code / Low-code
--   Softr — No-code / Low-code
--   Glide — No-code / Low-code
--   Adalo — No-code / Low-code
--   FlutterFlow — No-code / Low-code
--   Retool — No-code / Low-code
--   (наявний) Bubble → No-code / Low-code
--   (наявний) Airtable → No-code / Low-code
--
-- Застосування (phpMyAdmin хостингу, БД gu621051_ailabhublive): «Импорт» → *.sql.zip → «Импорт» (або SQL → вставити → Вперёд).
-- Без фіксованих id і без DROP / DELETE. @new обчислюється ДО вставки продукту (без ROW_COUNT()); продукт додається
-- лише якщо немає продукту з тим самим нормалізованим URL АБО назвою, інакше наявному лише додаються категорія й
-- підкатегорія. Id тарифів — за product_id + plan_name. Повторний запуск безпечний.
-- Автор — whitevelvetelf@gmail.com (id за email). Статус published, партнерство «Знайдено».
-- =====================================================================

INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'No-code / Low-code', 'No-code / Low-code', 'no-code-low-code' FROM `categories` c WHERE c.`slug` = 'development-it' LIMIT 1;

SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);

-- Lovable — No-code / Low-code
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lovable.dev' OR LOWER(`name`) = LOWER('Lovable'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Lovable', NULL, 'https://lovable.dev', NULL, NULL, 'AI-конструктор вебзастосунків: описуєте ідею в чаті — і Lovable створює сайт чи застосунок з базою даних, хостингом і власним доменом, без знання програмування.', 'An AI web app builder: describe your idea in chat and Lovable builds a website or app with a database, hosting and a custom domain, with no coding knowledge needed.', 'Lovable позиціонує себе як AI-інженера, з яким кожен може створювати продукти для вебу. Ви описуєте, що потрібно, звичайною мовою, а Lovable генерує повноцінний вебзастосунок і доопрацьовує його за наступними повідомленнями; є режим планування, де AI спершу узгоджує план змін. Проєкти одразу розгортаються в хмарі Lovable з базою даних і хостингом, їх можна публікувати на піддомені lovable.app чи власному домені, працювати разом із командою та налаштовувати ролі. Оплата — кредитами за повідомлення. Тарифи: Free — 5 кредитів на день (до 30 на місяць); Pro — $25 на місяць (100 кредитів, перенесення залишку, власні домени); Business — $50 на місяць (командний простір, рольовий доступ, SSO); Enterprise — за запитом.', 'Lovable presents itself as an AI software engineer that lets anyone build for the web. You describe what you need in plain language, Lovable generates a full web app and refines it with each follow-up message; a plan mode lets the AI agree a plan of changes first. Projects deploy straight to Lovable Cloud with a database and hosting, can be published on a lovable.app subdomain or your own domain, and support team collaboration and roles. Usage is paid in credits per message. Plans: Free — 5 credits a day (up to 30 a month); Pro — $25 a month (100 credits, credit rollover, custom domains); Business — $50 a month (team workspace, role-based access, SSO); Enterprise on request.', 'Створення вебзастосунку з опису в чаті
Хмара Lovable: база даних і хостинг
Режим планування змін
Власні домени та командна робота', 'Builds a web app from a chat description
Lovable Cloud: database and hosting
Plan mode for changes
Custom domains and team collaboration', 'Підприємці, продакт-менеджери й дизайнери, які хочуть швидко зробити MVP чи внутрішній інструмент без розробників.', 'Founders, product managers and designers who want to ship an MVP or internal tool quickly without developers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lovable.dev' OR LOWER(`name`) = LOWER('Lovable')) ORDER BY `id` LIMIT 1);
