INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Lovable presents itself as an AI software engineer that lets anyone build for the web. You describe what you need in plain language, Lovable generates a full web app and refines it with each follow-up message; a plan mode lets the AI agree a plan of changes first. Projects deploy straight to Lovable Cloud with a database and hosting, can be published on a lovable.app subdomain or your own domain, and support team collaboration and roles. Usage is paid in credits per message. Plans: Free — 5 credits a day (up to 30 a month); Pro — $25 a month (100 credits, credit rollover, custom domains); Business — $50 a month (team workspace, role-based access, SSO); Enterprise on request.', 'manual' FROM DUAL WHERE @new = 1;
