SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bolt.new' OR LOWER(`name`) = LOWER('Bolt.new'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Bolt.new', NULL, 'https://bolt.new', NULL, NULL, 'AI-конструктор сайтів і застосунків від StackBlitz: з текстового опису створює повноцінний застосунок з хостингом і базою даних прямо в браузері.', 'An AI site and app builder from StackBlitz: from a text description it creates a full app with hosting and a database right in the browser.', 'Bolt.new від StackBlitz дає змогу створювати сайти, дашборди, інтернет-магазини та внутрішні застосунки без програмування: ви пишете, що потрібно, а AI генерує й запускає застосунок прямо в браузері, після чого його можна доопрацьовувати в чаті чи вручну в коді. Безкоштовно доступні публічні й приватні проєкти, хостинг і бази даних. Тарифи: Free — до 300 тис. токенів на день і 1 млн на місяць; Pro — $25 на місяць (10 млн токенів, без брендингу Bolt, власні домени, AI-редагування зображень); Teams — $30 за учасника на місяць; Enterprise — за запитом, з SSO та журналами аудиту.', 'Bolt.new by StackBlitz lets you build websites, dashboards, storefronts and internal apps without coding: you write what you need, the AI generates and runs the app right in the browser, and you can then refine it in chat or by hand in the code. Public and private projects, hosting and databases are available for free. Plans: Free — up to 300K tokens a day and 1M a month; Pro — $25 a month (10M tokens, no Bolt branding, custom domains, AI image editing); Teams — $30 per member a month; Enterprise on request, with SSO and audit logs.', 'Застосунок з текстового опису прямо в браузері
Хостинг і бази даних
Редагування в чаті або в коді
Власні домени (Pro)', 'App from a text description right in the browser
Hosting and databases
Edit in chat or in code
Custom domains (Pro)', 'Підприємці, малий бізнес і розробники, яким потрібен робочий прототип чи застосунок за кілька годин.', 'Founders, small businesses and developers who need a working prototype or app within hours.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
