-- Softr — No-code / Low-code
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'softr.io' OR LOWER(`name`) = LOWER('Softr'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Softr', NULL, 'https://www.softr.io', NULL, NULL, 'No-code конструктор бізнес-застосунків з AI: внутрішні інструменти, клієнтські портали й CRM з базою даних, автоматизаціями та інтеграціями.', 'A no-code business app builder with AI: internal tools, client portals and CRMs with a database, workflow automation and integrations.', 'Softr — AI-конструктор застосунків для бізнес-операцій. На ньому без коду збирають внутрішні інструменти, клієнтські й партнерські портали, CRM, системи заявок та інші застосунки з вбудованою базою даних або підключенням до Airtable, Google Sheets та інших джерел. Є автоматизація процесів, AI-функції всередині застосунків, керування доступами й безпека корпоративного рівня. Softr довіряють понад мільйон компаній. Тарифи (при річній оплаті): Free; Basic — $19 на місяць; Pro — $99 на місяць; Business — $329 на місяць; кожен тариф включає певну кількість AI-кредитів, є безкоштовний пробний період.', 'Softr is an AI app builder for business operations. Without code you can assemble internal tools, client and partner portals, CRMs, request systems and other apps with a built-in database or connections to Airtable, Google Sheets and other sources. It includes workflow automation, AI features inside apps, access control and enterprise-grade security. More than a million businesses trust Softr. Plans (billed yearly): Free; Basic at $19 a month; Pro at $99 a month; Business at $329 a month; each plan includes a set number of AI credits, and there is a free trial.', 'Внутрішні інструменти, портали й CRM без коду
Вбудована база даних та інтеграції
Автоматизація процесів
AI-функції в застосунках', 'Internal tools, portals and CRMs without code
Built-in database and integrations
Workflow automation
AI features inside apps', 'Малий і середній бізнес, операційні команди та агенції, яким потрібні власні бізнес-застосунки.', 'Small and mid-sized businesses, operations teams and agencies that need their own business apps.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
