-- FlutterFlow — No-code / Low-code
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'flutterflow.io' OR LOWER(`name`) = LOWER('FlutterFlow'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FlutterFlow', NULL, 'https://flutterflow.io', NULL, NULL, 'Візуальний low-code конструктор застосунків на Flutter для мобільних, вебу й десктопу, з AI-генерацією, 1 000+ шаблонів і можливістю завантажити код.', 'A visual low-code Flutter app builder for mobile, web and desktop, with AI generation, 1,000+ templates and code export.', 'FlutterFlow — платформа візуальної розробки застосунків на Flutter. Екрани збираються з компонентів або понад 1 000 готових шаблонів, AI допомагає генерувати сторінки й логіку, а дані підключаються через API та бази даних. З одного проєкту виходять мобільні, веб- і настільні застосунки, які можна тестувати прямо в редакторі. На платних тарифах доступне завантаження коду й APK, на командних — спільна робота в реальному часі, гілки та інтеграція з GitHub. Тарифи (помісячно): Free — до 2 проєктів; Basic — $39; Growth — $80 за перше місце; Business — $150 за перше місце; при річній оплаті приблизно на 25% дешевше.', 'FlutterFlow is a visual development platform for Flutter apps. Screens are built from components or 1,000+ ready templates, AI helps generate pages and logic, and data connects through APIs and databases. One project produces mobile, web and desktop apps that you can test right in the editor. Paid plans let you download the code and APK, and team plans add real-time collaboration, branching and GitHub integration. Plans (monthly): Free — up to 2 projects; Basic — $39; Growth — $80 for the first seat; Business — $150 for the first seat; about 25% cheaper billed yearly.', 'Візуальна розробка на Flutter
Мобільні, веб- і настільні застосунки
AI-генерація сторінок і 1 000+ шаблонів
Завантаження коду та APK
GitHub і спільна робота', 'Visual Flutter development
