SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'retool.com' OR LOWER(`name`) = LOWER('Retool'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Retool', NULL, 'https://retool.com', NULL, NULL, 'Low-code платформа для внутрішніх інструментів, автоматизацій і AI-агентів компанії, підключених до ваших баз даних, API та сервісів.', 'A low-code platform for a company''s internal tools, automations and AI agents, connected to your databases, APIs and services.', 'Retool допомагає розробникам, аналітикам і бізнес-командам швидко створювати внутрішні застосунки — адмінки, панелі підтримки, дашборди — та автоматизовані процеси, підключені до власних баз даних і API. Інтерфейс збирається з готових компонентів, логіка пишеться на JavaScript і SQL, а AI допомагає генерувати застосунки й будувати агентів. Тарифи — за користувача на місяць: Free — до 5 користувачів і 500 запусків процесів; Team — $12 за розробника і $7 за внутрішнього користувача; Business — $65 і $18; при річній оплаті на 20% дешевше; Enterprise — за запитом, з SSO, журналами аудиту й контролем версій.', 'Retool helps developers, analysts and business teams quickly build internal apps — admin panels, support consoles, dashboards — and automated workflows connected to their own databases and APIs. The UI is assembled from ready-made components, logic is written in JavaScript and SQL, and AI helps generate apps and build agents. Plans are per user a month: Free — up to 5 users and 500 workflow runs; Team — $12 per builder and $7 per internal user; Business — $65 and $18; 20% cheaper billed yearly; Enterprise on request, with SSO, audit logs and source control.', 'Внутрішні застосунки з готових компонентів
Підключення до баз даних і API
